mapper.select:
SELECT plan.id AS planId,
plan.name AS planName,
plan.status AS planStatus,
plan.start_time AS planStartTime,
plan.end_time AS planEndTime,
participant.id AS participantId,
participant.status AS participantStatus,
participant.expiry_time AS participantExpiryTime,
participant.join_time AS participantJoinTime,
participant.created_time AS inviteTime,
merchant.id AS merchantId,
merchant.name AS merchantName

FROM merchants AS merchant
JOIN joint_marketing_plan AS plan ON merchant.id = plan.initiator_merchant_id
JOIN joint_marketing_participant AS participant ON plan.id = participant.plan_id

WHERE participant.merchant_id = #{dto.merchantId}
AND plan.is_deleted = 0 AND participant.is_deleted = 0 AND merchant.is_deleted = 0

    AND plan.initiator_merchant_id IN

        #{id}



    AND participant.status = #{dto.status}


    AND participant.created_time >= #{dto.inviteStartTime}


    AND participant.created_time <= #{dto.inviteEndTime}


    AND participant.join_time >= #{dto.acceptStartTime}


    AND participant.join_time <= #{dto.acceptEndTime}



    ORDER BY participant.created_time ${dto.orderByAsc ? 'ASC' : 'DESC'}
